    ["8b823dc"] = "Zygor 尚未就緒。",
    ["7496082"] = "Zygor 天賦標記：",
    ["1b9f260"] = "請重新開啟天賦視窗。",
    ["7c4161e"] = "切換目標時不會中斷自動射擊。",
    ["3ddfa3b"] = "寵物攻擊你用 Hunter's Mark 標記的目標。",
    ["d00e00c"] = "一個按鍵使用近戰技能，用於被攻擊時。",
    ["458bcf6"] = "在閃避或招架之後，用一個按鍵輪流使用 Mongoose Bite 和 Counterattack。",
    ["7e3322d"] = "施放技能並開始自動攻擊，甚至在進入戰鬥之前。可以用別的技能代替 Heroic Strike。需要足夠的怒氣。",
    ["4215a24"] = "對游標下的敵人施放 Sunder Armor，無需選中它。",
    ["fade647"] = "對游標下的盟友施放 Blessing of Protection（沒有則對你的目標）。",
    ["0ea3265"] = "對游標下的盟友施放 Blessing of Freedom。",
    ["474ed6a"] = "對游標下的盟友施放 Cleanse。",
    ["dd398c9"] = "在游標處召喚 Advanced Target Dummy 並對它施放 Blessing of Protection：在沒有公共冷卻時按兩次。",
    ["ad171ca"] = "對自己施放 Divine Shield；再按一次立刻取消。在沒有公共冷卻時按兩次。",
    ["8b1f0a2"] = "開始自動攻擊並施放 Holy Strike。不要放在 Holy Shield 上。",
    ["39da0a5"] = "對游標目標施放 Power Word: Shield，否則對自己。",
    ["885b4fd"] = "對游標目標施放 Greater Heal，否則對當前目標，否則對自己。",
    ["f6044e4"] = "停止當前施法並重新施放 Greater Heal：當另一名治療已經治療了該目標時使用。",
    ["73afb8f"] = "Inner Focus，緊接著 Prayer of Healing：用於緊急情況。",
    ["91996ef"] = "智慧 Dispel Magic：驅散盟友身上的有害魔法和敵人身上的有益魔法。",
    ["b32d1df"] = "對游標目標施放 Prayer of Mending，否則對當前目標，否則對自己。",
    ["4e5454e"] = "停止施法，對正在逃跑的瀕死怪物或圖騰使用 Shadow Word: Death。",
    ["4b2ea52"] = "給主手武器塗抹 Deadly Poison；圖示顯示持續時間。",
    ["73d1f2d"] = "給副手武器塗抹 Instant Poison；圖示顯示持續時間。",
    ["672d6cc"] = "以 Pick Pocket 開場，然後 Garrote（可以換成 Cheap Shot 或 Ambush）。",
    ["c2da64b"] = "用一個按鍵讓寵物和角色一起攻擊：這樣升級時你不會站著不動。",
    ["8833bc9"] = "與 BB Attacco 相同，但還會施放 Stormstrike（代替前一個巨集）。",
    ["79e760c"] = "在游標所在位置施放 Totemic Projection。",
    ["93ec012"] = "Nature's Swiftness，緊接著對游標目標施放 Healing Wave：瞬發的緊急治療。如果不想用游標治療，請刪掉 [@mouseover]。",
    ["ddfe74e"] = "對焦點目標施放 Polymorph；如果沒有焦點或不是敵人，則對當前目標。",
    ["425c144"] = "用一個按鍵使用兩個飾品（欄位13和14）。",
    ["23fc3c4"] = "Combustion 與兩個飾品一起使用。",
    ["6d5d784"] = "讓寵物攻擊，然後設為被動，如指南所述。",
    ["3b9d855"] = "Amplify Curse 和 Bane of Agony 一起使用：用於開場或 Amplify Curse 就緒時。",
    ["67eb4db"] = "可以連續多次按下而不會打斷自己的 Drain Life。",
    ["c24583f"] = "對游標下的目標施放 Corruption：用來給多個敵人上 DOT。把 Corruption 換成別的 DOT 即可。",
    ["de046d0"] = "Fel Domination，緊接著 Imp：用於寵物死亡後重新召喚，或用於收割流派。",
    ["0da2d35"] = "Fel Domination，緊接著 Succubus：用於寵物死亡後重新召喚。",
    ["701f8c9"] = "對游標下的目標施放 Bane of Havoc。",
    ["6177927"] = "對焦點（Bane of Havoc 的目標）施放 Immolate。",
    ["687eb32"] = "對焦點施放 Corruption。",
    ["dfc9982"] = "對焦點施放 Bane of Doom。",
    ["f14c9c9"] = "對焦點施放 Bane of Agony。",
    ["37f2591"] = "在施法期間按鍵也不會自己打斷的 Hurricane。",
    ["e041704"] = "對游標目標施放 Moonfire：用來給多個敵人上 DOT（另一個換成 Insect Swarm）。",
    ["11b387e"] = "Feral Charge（獵豹），然後 Prowl（如果你還沒潛行）。",
    ["9bca5ec"] = "變換形態以擺脫定身和減速：從熊到獵豹，從獵豹到獵豹。",
    ["38e0846"] = "一個按鍵：水中用 Aquatic Form，室外用 Travel Form，否則 Cat Form。",
    ["53406a7"] = "只進入一次 Dire Bear Form，再按也不會退出。",
    ["b18da61"] = "對焦點施放 Growl，然後對游標目標，然後對當前目標。",
    ["beb6029"] = "Nature's Swiftness，緊接著 Healing Touch：瞬發的緊急治療（退出形態並停止施法）。",
    ["8c5c182"] = "戰鬥中無法建立巨集：請稍後再試。",
    ["e3c93a8"] = "巨集：建立 %d 個，更新 %d 個%s。用 /macro 開啟並拖到動作條上。",
    ["99effc3"] = "%d 個未建立（你已有18個角色巨集）",
    ["530c645"] = "這個專精沒有巨集。",
    ["1e74c8f"] = "BuildBeast 將為你的角色建立 %s 個巨集：\n%s\n\n如果已存在則更新。然後你把它們拖到動作條上。",
    ["d8354a3"] = "建立",
    ["160009a"] = "取消",
    ["054716f"] = "戰士",
    ["3e76e85"] = "聖騎士",
    ["69c8129"] = "獵人",
    ["dd6c053"] = "盜賊",
    ["3a3f441"] = "牧師",
    ["fabeb14"] = "薩滿",
    ["a5a0a92"] = "法師",
    ["8b0635d"] = "術士",
    ["3d8e8ed"] = "德魯伊",
    ["ce774d9"] = "是",
    ["c2f3f48"] = "否",
    ["672c529"] = "相近",
    ["656ff24"] = "Bear Form, Growl, Maul（職業任務）, Nature's Grasp, Demoralizing Roar",
    ["50d1ea3"] = "Bash；Cure Poison 的任務",
    ["2290f2a"] = "Swipe；Aquatic Form 的任務",
    ["227f378"] = "Faerie Fire（現在在變形狀態下也能用）, Hibernate",
    ["469f184"] = "Cat Form（任務）, Prowl, Claw, Rip, Shred, Starfire, Rebirth, Omen of Clarity",
    ["eda7053"] = "給自己上 Mark of the Wild。用 Wrath 開場並持續施放。法力不足時用武器收掉怪物，這樣法力會回來。戰鬥之間用 Healing Touch 治療。",
    ["3d495a9"] = "讓 Mark of the Wild 和 Thorns 一直在身上，戰鬥前先上 Rejuvenation。用 Wrath 開場，加上 Moonfire，然後繼續 Wrath。在怪物密集的地方用瞬發的 Moonfire 開場。",
    ["bb21cc8"] = "職業任務會給你 Bear Form、Growl 和 Maul。Nature's Grasp 會纏住下一個打到你的怪物；Demoralizing Roar 用於熊形態。",
    ["a9ba21f"] = "Enrage 立刻給你怒氣，10秒後再給一些，但會降低你的護甲。",
    ["9c7f3ca"] = "Feral 是貓和熊的專精，也是升級最順暢的：Prowl 和 Dash 把你從一個目標帶到下一個，幾乎不會因為法力而停下。在 Bear Form 中：給自己上 Mark of the Wild 和 Thorns，用打擊獲得的怒氣支付 Maul，它會給下一次打擊增加傷害。面對多個怪物用 Demoralizing Roar 削弱它們。",
    ["ce230c2"] = "在 Bear Form 中：拉怪前用 Enrage（護甲損失影響較小），Faerie Fire 降低怪物護甲，Swipe 是填充技能，Maul 消耗多餘的怒氣。有多個怪物時先 Demoralizing Roar，再 Swipe。",
    ["78a0920"] = "Cat Form：先上 Mark of the Wild 和 Thorns。從 Prowl 用 Shred 開場（Prowl 帶你繞到怪物背後），然後 Faerie Fire，再用 Claw 積累連擊點，或在背後時用 Shred。有四個或更多連擊點時，如果怪物活得夠久就用 Rip。面對多個怪物 Bear Form 仍然更好：貓形態沒有能同時打多個目標的技能。",
    ["540175c"] = "Rake：從 Prowl 用 Shred 開場，Faerie Fire，然後 Rake，並讓它的流血始終保持在活得夠久的怪物身上；然後從背後用 Claw 或 Shred。有4個或更多點時：怪物還活著就用 Rip，用 Ferocious Bite 收尾。",
    ["87e3251"] = "Lacerate（熊）：可疊加最多5層的流血；面對單個怪物它是你的填充技能，Maul 消耗多餘的怒氣。有多個怪物時用 Demoralizing Roar 然後 Swipe。Blood Frenzy：熊形態下每次暴擊給5點怒氣，貓形態下用連擊點技能暴擊會多給一個點。",
    ["25dc320"] = "Predatory Discipline：Ferocious Bite 仍會從多餘的能量中獲得傷害，但不會消耗它。",
    ["042c952"] = "Ravage：從 Prowl 用 Ravage 開場（必須在怪物背後），然後 Faerie Fire，保持流血的 Rake，然後從背後用 Claw 或 Shred；有4個或更多點時用 Rip 或 Ferocious Bite 收尾。如果以滿能量開場，Poised 會讓你的第一擊少消耗10點能量。",
    ["4560b4d"] = "Dire Bear Form：拉怪前用 Enrage，Faerie Fire，每次冷卻好就用 Primal Bite（強力撕咬，冷卻6秒，威脅很高），面對單個怪物在中間用 Lacerate，用 Maul 消耗剩餘怒氣；有多個怪物時用 Demoralizing Roar 和 Swipe 代替 Lacerate。",
    ["ff10d54"] = "貓：能量低於50時用 Shifting Power（把法力變成40點能量，冷卻8秒）。",
    ["0d8ecd7"] = "Feral 最看重武器的每秒傷害，因為你的形態基於它，而武器速度不重要。然後是命中（Hit）、暴擊、敏捷和力量。",
    ["4a841e3"] = "Guardian 就是熊：使用與 Feral 相同的天賦計劃。Bear Form，給自己上 Mark of the Wild 和 Thorns；打擊得到的怒氣支付 Maul。面對多個怪物用 Demoralizing Roar。",
    ["7b551a8"] = "拉怪前 Enrage，對怪物用 Faerie Fire，Swipe 作填充，Maul 消耗多餘的怒氣。有多個怪物時 Demoralizing Roar 然後 Swipe。",
    ["af4c8fb"] = "Lacerate 是你面對單個怪物的填充技能（最多疊加5層）；Maul 消耗多餘的怒氣。有多個怪物時用 Demoralizing Roar 和 Swipe。",
    ["5213241"] = "Dire Bear Form：拉怪前 Enrage，Faerie Fire，每次冷卻好就用 Primal Bite（6秒，威脅很高），面對單個怪物在中間用 Lacerate，Maul 消耗其餘怒氣；有多個怪物時用 Demoralizing Roar 和 Swipe 代替 Lacerate。",
    ["fc61247"] = "熊想要武器的每秒傷害（速度不重要），然後是命中（Hit）、暴擊、敏捷和力量。熊形態下力量和法術強度也可以，如果你坦怪，耐力更重要。",
    ["25acd2a"] = "Balance 和 Restoration 開局相同：Improved Wrath（施法時間減半秒、法力消耗減半）和 Nature's Focus。Balance 起步慢，但當 Insect Swarm 在每個怪物身上和 Moonfire 疊加時會變快。",
    ["9c1fb9f"] = "給自己上 Mark of the Wild 和 Thorns，戰鬥前上 Rejuvenation。用 Wrath 開場，區域怪物密集時用 Moonfire。給怪物上 Moonfire 和 Insect Swarm（一個還會降低其命中率的 DOT），然後 Wrath。需要治療時用 Regrowth，在第二個怪物到來前用 Nature's Grasp。",
    ["7f51b3b"] = "給你戰鬥的每個怪物上 Moonfire 和 Insect Swarm，然後 Wrath。有三個或更多怪物時用 Hurricane。",
    ["c845919"] = "有三個或更多怪物時，Barkskin 然後 Hurricane。",
    ["d66aa4c"] = "Eclipse：每個 Wrath 會讓你接下來的兩個 Starfire 各減少半秒，所以 Starfire 終於進入輸出循環：一個 Wrath 後接兩個 Starfire。",
    ["7e94c11"] = "Moonkin Form：護甲很高，為隊伍提供3%暴擊，Omen of Clarity 觸發率翻倍；處於該形態時不能施放治療，所以退出形態用 Regrowth 再進入。輸出循環：Moonfire 和 Insect Swarm，然後一個 Wrath 和兩個 Starfire。",
    ["ef6797a"] = "對 Balance 和 Restoration，法術強度排第一，然後是智力、暴擊和精神；Restoration 在60級加上治療強度。施法者法杖可以來自陣營任務。",
    ["a91a8ac"] = "Restoration 升級最慢，因為治療不能殺怪：你可以用 Balance 或 Feral 升級，仍然可以治療副本。",
    ["7a2110b"] = "給自己上 Mark of the Wild 和 Thorns，戰鬥前上 Rejuvenation。在怪物密集的區域用 Wrath 或 Moonfire 開場，然後給怪物上 Moonfire 和 Insect Swarm，再 Wrath。需要治療時用 Regrowth，在第二個怪物到來前用 Nature's Grasp。",
    ["937f66e"] = "Swiftmend：瞬間治療帶有你的 Rejuvenation 或 Regrowth 的目標。受到傷害時，對你的 Rejuvenation 用 Swiftmend，需要更多時再用 Regrowth。有三個或更多怪物時用 Hurricane。",
    ["2061d06"] = "Nature's Swiftness：你的下一個自然法術是瞬發。把它放在輸出循環之外，留給需要立刻大量治療的時刻。",
    ["1164b95"] = "Wild Growth：在7秒內治療目標及其隊伍，開始時更強：隊伍裡不止一個人受傷時使用。",
    ["8f8a34a"] = "Aspect of the Hawk，馴服寵物（職業任務：Tame Beast、Call Pet、Feed Pet、Revive Pet）",
    ["2b3db50"] = "Auto Shot 會自動開始：每次射擊前站定半秒，讓怪物靠近。如果它追上你就用 Raptor Strike。8碼以內遠端射擊無效。",
    ["9329f10"] = "開場時加上 Serpent Sting，只對能活得久的怪物使用：如果它幾秒就死了，傷害就浪費了。",
    ["d2b7bf1"] = "拉怪前 Hunter's Mark，然後 Serpent Sting。有法力時用 Arcane Shot。",
    ["85f72cd"] = "核心是 Auto Shot，有法力時加 Arcane Shot。拉怪前 Hunter's Mark，然後以 Serpent Sting 開場。怪物向你衝來時 Concussive Shot 減速它；如果它追上你就用 Raptor Strike。",
    ["71067ff"] = "你有寵物：先讓它衝上去幾秒，然後 Serpent Sting。始終保持 Aspect of the Hawk 並給寵物餵食。怪物轉向你時用 Concussive Shot，最後手段才用 Raptor Strike。",
    ["bb6f64b"] = "Rapid Fire（15秒內攻擊速度+40%）不放進輸出循環：留給需要它的那次拉怪。",
    ["ebe54cf"] = "核心是每次冷卻好就用 Aimed Shot（2秒施法，6秒冷卻與 Multi-Shot 共享），空檔用 Auto Shot。拉怪前 Hunter's Mark，寵物先上，然後 Serpent Sting。有法力時用 Arcane Shot。如果怪物追上你：Disengage。有多個怪物時：用 Multi-Shot 代替 Aimed Shot。",
    ["c943332"] = "核心是獵鷹（Summon Hawk）：每隻獵鷹持續18秒，可以同時存在兩隻；兩隻中有一隻消失時召喚新的。然後冷卻好時用 Aimed Shot，空檔用 Auto Shot。Arcane Shot 與獵鷹共用冷卻，所以放在它們之後。其餘同前。",
    ["ab9f050"] = "加上 Intimidation：如果怪物轉向你，它會擊暈並給寵物威脅；沒準備好時用 Disengage。有多個怪物時：先 Explosive Trap，然後在 Aimed Shot 的冷卻期用 Multi-Shot。",
    ["bf06335"] = "Bestial Wrath（2分鐘）和 Volley 不放進輸出循環：在危險的拉怪或大群怪時手動使用。從42級起幾乎所有點數都投入 Marksmanship：輸出循環不變。",
    ["e096af7"] = "Beast Mastery 從遠處射擊：遠端武器DPS最重要，然後是敏捷。近戰武器只因它的屬性而需要。",
    ["b35c3c9"] = "核心是每次冷卻好就用 Aimed Shot，空檔用 Auto Shot。在寵物搶先之後，第一擊必須是最強的：有 Rapid Killing 待命時就是 Aimed Shot。拉怪前 Hunter's Mark 並讓寵物先上；對每個怪物用 Serpent Sting，因為如果它帶著 Serpent Sting 死去，你20秒內的下一擊最多多造成20%傷害。有法力時用 Arcane Shot。如果怪物追上你：Disengage。有多個怪物時：用 Multi-Shot 代替 Aimed Shot。",
    ["cf4e14e"] = "拉怪前除了 Hunter's Mark 還要 Trueshot Aura。",
    ["51e16cf"] = "Sniper Shot 是你最強的射擊：4秒施法，15秒冷卻，最遠45碼，並且在10秒內你接下來的三次射擊會遠10碼。當你有時間施法時把它作為寵物搶先後的第一擊，最好有 Rapid Killing 待命；否則用 Aimed Shot。有多個怪物時：先 Explosive Trap，然後在 Aimed Shot 的冷卻期用 Multi-Shot。",
    ["c8aaa16"] = "核心是獵鷹（Summon Hawk）：兩隻中每消失一隻就召喚一隻新的。然後冷卻好時用 Aimed Shot，空檔用 Auto Shot；有時間時第一擊用 Sniper Shot。Arcane Shot 放在獵鷹之後。",
    ["1fe9ee6"] = "Marksmanship 從遠處射擊：遠端武器DPS重要（其他條件相同，更慢但單次傷害大的更好，因為 Aimed Shot 基於一次武器攻擊）以及敏捷。有 Careful Aim 時，智力除了法力外也算攻擊強度。近戰武器只因它的屬性而需要。",
    ["184fc61"] = "Survival 在兩個地方戰鬥。遠端：每次冷卻好就用 Multi-Shot（它是瞬發，與 Aimed Shot 共享冷卻，所以你幾乎不用 Aimed Shot），加上 Serpent Sting、Arcane Shot 和 Auto Shot。近戰：Immolation Trap，然後 Raptor Strike（瞬發，冷卻6秒）和閃避後的 Mongoose Bite。拉怪前 Hunter's Mark，寵物先進場。",
    ["d85837a"] = "Strider Kick：一記造成武器全額傷害的踢擊，讓你3秒內加速30%：它是結束近戰並讓你回到遠端的按鍵。近戰時先 Immolation Trap，可用時 Mongoose Bite，然後 Raptor Strike。遠端時冷卻好就 Multi-Shot，Serpent Sting，Arcane Shot，Auto Shot。有多個怪物時 Explosive Trap 取代 Immolation Trap，因為所有陷阱共用一個冷卻。",
    ["e7233e1"] = "有 Lacerating Strikes 時，每次 Mongoose Bite 會留下一個流血，傷害為該擊傷害的40%，持續21秒。",
    ["10bfe36"] = "Survival 會射擊，但也用近戰武器攻擊（Raptor Strike 和 Strider Kick 基於它的傷害）：慢速雙手武器有幫助。然後敏捷重要。從49級起，Careful Aim 讓智力也能當作攻擊強度。",
    ["0718298"] = "Blink, Evocation, Mana Shield, Blizzard, Fire Ward, 傳送到兩座主城（以及 Arcane 和 Fire 的 Arcane Blast）",
    ["ad986c1"] = "Conjure Mana Agate（第一顆法力寶石）",
    ["3e67dd9"] = "Ice Armor；職業任務（魔杖 Ice Fury）",
    ["3ddbf7c"] = "Frostfire Bolt，第一批傳送門",
    ["3d9e7fb"] = "始終保持 Arcane Intellect 和一個護甲法術（目前是 Frost Armor）。每次施放消耗法力的法術後，法力回覆會暫停5秒：快死的怪物不值得一次完整施法。5級前後弄一把魔杖（附魔師會給你做 Lesser Magic Wand，13級起是 Greater Magic Wand）：在有天賦之前，它造成的傷害可以和你的法術一樣多甚至更多，而且不耗法力。",
    ["2991425"] = "用 Frostbolt 在最大射程開場，讓怪物減速著到來。它靠近時繼續施法，然後 Fire Blast 收尾，剩下的用魔杖。",
    ["5d6b9a7"] = "Frost Nova 凍結你周圍的一切：受到傷害會打破冰凍，所以你可以後退並繼續施法。如果怪物到了近戰：Frost Nova 然後後退。",
    ["11f2d67"] = "有 Missile Barrage 時：從遠處用 Frostbolt（Arcane 和 Frost）或 Fireball（Fire）開場，繼續施法，觸發時施放 Arcane Missiles：它們變成一次免費的齊射。Missile Barrage 是升級時最能省法力的天賦。",
    ["b985201"] = "Evocation 是8秒的引導，能還給你大部分法力。跑動時冷卻好就用 Blink，能讓你大約快五分之一到達。爐石更適合用於任務區域，因為傳送已經把你帶到主城。",
    ["a601e53"] = "Arcane Blast：每次施放給你相當於你智力12%的法術傷害，最多4層，持續18秒；每層使下一次施放消耗增加100%。從遠處 Frostbolt，然後 Arcane Blast 一到三次，直到 Missile Barrage 觸發，再 Arcane Missiles。讓層數自然消失，不要疊到四層。把 Clear Casting 用在已疊層的 Arcane Blast 上。近戰時：Frost Nova 然後後退。Fire Blast 收尾，再用魔杖。",
    ["e55eb73"] = "Arcane Wrath：冷卻6秒的重擊（額外傷害相當於你最大法力的5%）。從遠處 Frostbolt，然後 Arcane Wrath，Arcane Blast 一到三次直到 Missile Barrage 和 Arcane Missiles；它靠近時 Frost Nova，再來 Arcane Wrath，然後 Fire Blast 和魔杖擊殺。讓層數自然消失，否則不斷上升的消耗會把你掏空；Clear Casting 只用在已疊層的 Arcane Blast 或 Arcane Wrath 上，絕不要用在便宜的法術上。",
    ["65a5bf0"] = "Presence of Mind：你的下一個施法時間低於10秒的法術變為瞬發。",
    ["c51b464"] = "Arcane Power：15秒內傷害+30%，代價是法力消耗+30%。",
    ["dfc4101"] = "從遠處用 Pyroblast 或 Frostbolt 開場，然後 Arcane Wrath。Arcane Blast 一到三次直到 Missile Barrage，然後是飛彈。從58級起冷卻好就用 Fire Blast，Heating Up 達到3層時用 Pyroblast。",
    ["9226a40"] = "對每個專精，法術強度排第一，因為你的法術隨它大幅成長。智力提高法力和少許暴擊；精神減少喝水的停頓，對 Arcane 來說很重要，因為它法力消耗很快。",
    ["ebbbb02"] = "從遠處 Fireball。一兩次 Arcane Blast 直到 Missile Barrage 觸發，然後是飛彈。冷卻好就 Fire Blast。血量少的怪物不需要保持距離：讓它打你幾下，低於15%時用魔杖收掉。",
    ["9e5f918"] = "即使怪物貼在身上，Scorch 也能填補空檔。",
    ["ab79a6b"] = "從遠處用 Frostfire Bolt 開場，然後一兩次 Arcane Blast 直到 Missile Barrage 觸發，再是飛彈。冷卻好就 Fire Blast，用 Scorch 填補空檔，最後15%用魔杖。",
    ["bece8ec"] = "Pyroblast 與 Heating Up：Fireball、Frostfire Bolt、Fire Blast 或 Scorch 的每次非週期性暴擊，會讓你下一個 Pyroblast 加快四分之一，最多3層，而 Fire Blast 每次造成傷害都會增加一層。當 Heating Up 達到3層時施放 Pyroblast。",
    ["196edb9"] = "對每個專精，法術強度排第一。智力提高法力和少許暴擊；精神減少喝水的停頓。",
    ["38bc29a"] = "Frost 從 Precision 開始：兩點就能讓你對同等級怪物的命中率達到100%。",
    ["c690916"] = "Frostbite：你的冰霜效果有15%的機率凍結目標5秒。Ice Lance（27級起）：對被凍結的目標多造成300%傷害，冷卻8秒，與 Fire Blast 共享。",
    ["1f1ed9a"] = "從遠處 Frostbolt，怪物到來時繼續施法。當 Frostbite 凍結目標時：一個 Frostbolt 緊跟 Ice Lance；如果 Ice Lance 沒準備好，就用 Cone of Cold。近戰時：Frost Nova 然後後退，再對被凍結的怪物用 Frostbolt 和 Ice Lance。Missile Barrage：施放飛彈，或者如果這個怪物快死了就留給下一個。對沒被凍結的低血怪物用 Fire Blast 或魔杖。",
    ["2e43c7c"] = "有 Fingers of Frost 時，你接下來的兩個法術會把目標視為被凍結：第一個用在 Frostbolt 上，第二個用在帶 Ice Lance 的 Frostbolt 上（如果 Ice Lance 還沒好，就用 Cone of Cold）。它的強項在30多級：Shatter 之後，被凍結的目標會承受你最重的打擊。",
    ["cecd125"] = "先上 Ice Barrier，一分鐘結束時再放一次：除了護盾，它還讓你一分鐘內的冰霜傷害增加15%。",
    ["959453a"] = "Winter's Chill：Frostbolt 和 Ice Lance 把它疊加在目標上，最多5層，下一個 Cone of Cold 每層多造成20%傷害。",
    ["5a9d3eb"] = "Redemption（職業任務）",
    ["3d343ad"] = "Seal of Command（Retribution 天賦）, Seal of Justice",
    ["32b558d"] = "雙專精和坐騎",
    ["38d0905"] = "拉怪前 Blessing of Might 和 Devotion Aura。然後三步：Seal of Righteousness，向怪物跑去時用 Judgment，Holy Strike。之後，Judgment 和 Holy Strike 每次冷卻好就用，只在聖印快結束時才重新整理（Judgment 不再消耗聖印，並且不佔公共冷卻）。法力也是你的治療：如果下一擊能殺死怪物，就跳過這個按鍵。如果戰鬥結束時法力有剩餘，用 Holy Light 把它變成生命。危險時：先給自己 Divine Protection，然後治療。",
    ["f580de7"] = "當你對付多個敵人或法力有餘時用 Consecration：它比 Judgment 和 Holy Strike 加起來還貴，需要8秒才能造成全部傷害。對每個亡靈或惡魔用 Exorcism，甚至可以30碼外使用。",
    ["2ea2c89"] = "加上 Hammer of Wrath：它能收掉生命值低於20%的敵人。",
    ["c8d4778"] = "Retribution 和 Protection 在同一棵樹裡開始，天賦幾乎相同。你可以選 Benediction 代替 Deflection（5%招架）：所有瞬發技能少消耗10%法力，Consecration 也更容易負擔。",
    ["a81d5b1"] = "有 Seal of Command 時：Blessing of Kings 或 Might 和 Retribution Aura。對活得久的怪物：先用 Seal of the Crusader 的 Judgment（怪物受到更多神聖傷害），然後如果你有慢速武器就換成 Seal of Command；用快速武器或法術傷害很多時 Seal of Righteousness 更好。然後每次冷卻好就 Judgment 和 Holy Strike。竅門：Seal of Command 的 Judgment 對被擊暈的目標幾乎翻倍，所以先 Hammer of Justice 再 Judgment。",
    ["733e5e6"] = "Sacred Arbiter：Holy Strike 的傷害提高20%，並重新整理目標身上的每個 Judgment，包括其他聖騎士的。",
    ["a01f90a"] = "Champion of the Light 把你最多60%的智力轉化為法術傷害：帶法術強度的裝備會變得更好。40級的 Unsealed Wrath：攻擊會保留當前聖印的副本（最多3個），換聖印又變得划算了。",
    ["5f3698b"] = "武器是最重要的：理想情況下帶法術強度且傷害高。有 Seal of Command 時，慢而重的武器最好（Holy Strike 和聖印造成更多傷害）。其餘屬性先看力量或攻擊強度，然後耐力，再是法術強度。",
    ["4c063de"] = "神聖系從懲戒系開始：前12點（到21級）投入懲戒，獲得更高的法力效率和正義追擊（Pursuit of Justice）。20級之前你的治療是 Holy Light、Lay on Hands 和 Blessing of Protection：單人做任務時，像輸出聖騎士一樣使用 Seal of Righteousness、Judgment 和 Holy Strike，不要浪費法力。",
    ["e1a4083"] = "有了 Flash of Light 你就有兩種治療：Holy Light 又慢又強，適合需要大量生命值且有時間的時候；Flash of Light 又快又省法力，適合小而持續的傷害。選對治療就是全部工作：選錯會白白燒法力。20級起還有 Consecration、Exorcism 和 Blessing of Kings。",
    ["42143bb"] = "22級起點數投入神聖：Spiritual Focus（受擊時施法被延遲得更少），然後是 Reverence（施法時仍保留一部分法力回復）和 Healing Light（提高 Holy Light、Flash of Light 和 Holy Shock 的治療量）。",
    ["a1c4391"] = "如何治療：坦克受到持續傷害時用 Flash of Light 或 Holy Light；突發傷害用 Holy Shock；緊急情況用 Lay on Hands（會耗盡全部法力）。Blessing of Protection 用在受到物理傷害的隊友身上，不要用在坦克身上：坦克免疫後敵人會轉向其他人。",
    ["e98c82f"] = "Illumination：Flash of Light、Holy Light 或 Holy Shock 的暴擊治療可以返還法力（基礎消耗的一半），所以智力和暴擊很重要。37級起把 Oath of Light 放在主要目標身上；38級起有 Infusion of Light：Holy Shock 或 Flash of Light 的暴擊治療會讓下一個 Holy Light 更快。",
    ["3bb92dd"] = "40級獲得雙天賦專精（把懲戒留作單人任務用的第二專精）和板甲。42級起有 Holy Shock：冷卻10秒的瞬發治療，或對敵人造成神聖傷害。45級起有 Divine Favor：下一次治療必定暴擊（冷卻2分鐘），用於坦克有危險時。47級起 Holy Power 提高 Holy Shock 和 Holy Strike 的暴擊機率。",
    ["31364c3"] = "Light's Vigil：給隊友施加30秒的效果；對同一目標使用 Holy Shock 會觸發它，同時治療隊伍，並且不會讓 Holy Shock 進入冷卻。消耗很大，每個隊伍只能有一個：留給多名玩家受傷的情況。對敵人使用會返還75%的法力。最後的點數（56級起）投入 Divine Intellect。",
    ["7fda0df"] = "對神聖系來說，首先是治療強度，其次是智力（更多法力和更多暴擊，暴擊透過 Illumination 返還法力），然後是每5秒回復法力和精神（有了 Reverence，施法時仍保留一部分回復）。武器看的是屬性而不是傷害：帶治療和精神的錘勝過 DPS 更高的武器。40級前穿鎖甲，之後穿板甲，但屬性合適的布甲比沒有屬性的鎖甲更有價值。",
    ["a531e3f"] = "Seal of Fury 是坦克的聖印：每次攻擊造成額外神聖傷害，持盾時你獲得相當於該傷害一半的吸收。它的 Judgment 讓你從10碼外嘲諷3秒。Righteous Fury 讓你的所有威脅提高33%。從22級起你轉入 Protection 天賦樹，在 Pursuit of Justice 之後。",
    ["8279baa"] = "Blessing of Kings、Retribution Aura 和 Righteous Fury 保持開啟。始終保持 Seal of Fury。向怪物跑去時用 Judgment 來嘲諷。法力允許時，一進入近戰就放 Consecration。然後每次冷卻好就 Holy Strike，對亡靈和惡魔用 Exorcism。聚集最多四個敵人，用 Consecration 把它們全部燒掉。",
    ["34e2900"] = "Shield Specialization：一次格擋返還4%的最大法力，最多每3秒一次：這是你法力的很大一部分。",
    ["cc3ac76"] = "Templar's Bulwark：一個護盾，8秒內吸收相當於你全部生命的傷害，但會給你 Forbearance 一分鐘。從37級起 Swift Judgement：聖印的 Judgment 會自動觸發，冷卻1分鐘，所以你多了一次嘲諷。",
    ["be55413"] = "Holy Shield：10秒內你格擋更頻繁，最多4次格擋造成神聖傷害。Reckoning（43級起）可在格擋或受到暴擊後給你一次額外攻擊。",
    ["e76d8e9"] = "對 Protection，法術強度排第一（Seal of Fury、Holy Shield 和 Consecration 造成神聖傷害），然後是力量和耐力。武器越快越好：Seal of Fury 每次攻擊都會觸發。帶法術強度的武器傷害低一點也值得。",
    ["05e5db7"] = "Shadow Word: Pain；簡短的職業任務（一件長袍）",
    ["c95888a"] = "Mind Blast, Resurrection；種族任務教你第一個只屬於你種族的技能",
    ["091c0cd"] = "Holy Fire, Flash Heal, Devouring Plague, Fear Ward, Mind Soothe, Shackle Undead；第二個種族技能",
    ["71b2a72"] = "拉怪前給自己上 Fortitude。用 Smite 開場，給目標上 Shadow Word: Pain，然後用魔杖收尾，魔杖不耗法力，開始時造成你傷害的很大一部分（使用前站定半秒）。如果怪物追上你，先 Power Word: Shield。最重要的是有一把好魔杖：每次找到更好的就換掉。",
    ["e023128"] = "Mind Blast 是冷卻短的強力一擊。前七個天賦點對所有專精都一樣：Wand Specialization（10-11）和 Spirit Tap（12-16）。有 Spirit Tap 時，每次擊殺會給經驗的怪物，都會讓你的精神翻倍15秒，期間一半的法力回覆在施法時繼續：喝水的停頓更少。",
    ["8df287d"] = "Inner Fire：額外護甲，每次受到攻擊消耗一層。讓它和 Fortitude 一直在你身上，結束時重新施放。",
    ["bebe913"] = "Psychic Scream 讓附近的敵人逃跑，但要小心：它們可能帶回其他怪物。",
    ["ffa87bf"] = "導師今天教你的比任何其他等級都多：Holy Fire（開場慢但強，還會持續灼燒）、Flash Heal（快但貴）、Devouring Plague（持續傷害並治療你）等等。",
    ["084f80e"] = "Shadow 是我們推薦的單人升級專精：點數投入 Shadow Word: Pain、Mind Blast 和 Mind Flay，讓怪物更快死亡。",
    ["f33a503"] = "如果怪物追上你，給自己上 Shield。用 Mind Blast 開場，然後 Shadow Word: Pain。從27級起還有 Devouring Plague 和 Mind Flay，並在 Shadow Word: Pain 之後加上 Vampiric Embrace，讓你的暗影傷害治療你。然後用魔杖收尾。法力低時跳過 Devouring Plague 和 Mind Flay。",
    ["496ef3d"] = "Shadow Word: Death 是突發傷害，但如果目標存活，你會承受你最大生命的30%：留給最後一擊。",
    ["edd0d02"] = "Shadowform：戰鬥時保持 Shadowform（暗影傷害+10%，暗影法術法力消耗減半，物理傷害-15%，但不能施放治療：治療前先退出）。用 Mind Blast 開場，然後 Shadow Word: Pain、Vampiric Embrace、Devouring Plague 和 Mind Flay。當再多一擊就能殺死怪物時：Shadow Word: Death，或把最後一點留給魔杖。如果怪物追上你，給自己上 Shield。",
    ["b912dce"] = "對 Shadow，法術強度排第一（暗影強度也行：你幾乎所有傷害都是暗影），然後是暴擊和命中（Hit）。魔杖非常重要：開始時它造成很大一部分傷害。",
    ["8e3f775"] = "Discipline 是我們推薦的單人遊玩治療專精：20級起 Power in Light 給 Smite 增加傷害。",
    ["916c9c2"] = "從遠處用 Holy Fire 開場，怪物到來時用 Smite，然後 Mind Blast、Shadow Word: Pain 和魔杖。如果戰鬥不順：給自己上 Shield，然後治療：需要快就 Flash Heal，有時間就 Heal。",
    ["a80f7e5"] = "Penance：一連串神聖攻擊，傷害敵人或治療盟友，冷卻12秒，第一擊立刻打出。",
    ["037a666"] = "先給自己上 Shield。從遠處用 Holy Fire 開場。怪物走來時 Smite，然後對同一目標 Penance，因為 Power in Light 讓它打得更重。然後 Mind Blast 和 Shadow Word: Pain。收尾時，如果一擊能殺死就 Shadow Word: Death，否則用魔杖。每次 Weakened Soul 消失，你就可以再次保護自己。",
    ["9d0affc"] = "Power Infusion：15秒內傷害和治療+20%，對自己或朋友：每次冷卻好就在開場前對自己施放。60級的 Inner Focus 用於緊急情況：下一個法術免費。",
    ["8e7cd8d"] = "對 Discipline 和 Holy 尋找治療強度和法力回覆，然後是智力和精神。選具有這些相同屬性的武器：是法杖還是帶副手的單手武器都無所謂。",
    ["c5c1351"] = "拉怪前給自己上 Shield 和 Renew。然後用 Holy Fire 開場，怪物到來時 Smite，Mind Blast 和 Shadow Word: Pain。能殺死時用 Shadow Word: Death 收尾，否則用魔杖。",
    ["575bdd0"] = "Holy Nova 傷害附近的每個敵人並治療隊伍：它很耗法力，所以在多個敵人貼身時使用，或在它免費時使用（43級起的 Searing Light：Holy Fire 可以讓下一個 Holy Nova 免費）。",
    ["6953353"] = "拉怪前給自己上 Shield、Renew 和 Prayer of Mending（目標下次受到傷害時治療，然後跳到隊伍中的另一人，冷卻10秒）。",
    ["a5c9096"] = "對 Holy 尋找治療強度和法力回覆，然後是智力和精神。選具有這些相同屬性的武器。",
    ["aa71e89"] = "Backstab（需要匕首，只能從背後）, Pick Pocket",
    ["2e3c463"] = "Slice and Dice, Sprint, Sap；職業任務（Blade of Cunning）",
    ["3a2246d"] = "Ambush（需要匕首）, Poised（被動）",
    ["8abd601"] = "Rupture；毒藥任務：Instant Poison 和 Crippling Poison",
    ["6c840ea"] = "Shank（Forever 的新技能）",
    ["f3d428e"] = "Mutilate（Assassination 天賦）",
    ["3e307c7"] = "Death Mark（Subtlety 天賦）, Slice and Dice 2級",
    ["f14c847"] = "Shank 2級",
    ["a554ba3"] = "走到怪物面前，有連擊點時用 Sinister Strike，然後 Eviscerate：點數越多，打擊越強。Stealth 暫時可以留在動作條上。如果戰鬥不順：用 Evasion 和 Gouge 打斷施法或爭取幾秒鐘。",
    ["44b2b7e"] = "Slice and Dice（終結技：你的攻擊快20%，點數越多持續越久）、Sprint（15秒內快50%，不會打破 Stealth）和 Sap，用來在開戰前把一個人形生物移出戰鬥。",
    ["665b56f"] = "Rupture：點數越多，流血越久。有毒藥任務時，Instant Poison 和 Crippling Poison。",
    ["d06b2e0"] = "Shank：不會未命中的副手攻擊；第一級消耗5點能量，返還15點，10秒冷卻。從26級起從潛行用 Cheap Shot：擊暈4秒並給2個點。",
    ["6974c7f"] = "Combat 是決鬥者：用你喜歡的武器近戰，適用於任何武器，開始時不需要潛行。它是我們推薦的單人升級專精。",
    ["cea5a19"] = "Riposte：你招架之後亮起，造成一倍半的武器傷害，繳械怪物6秒，只消耗10點能量，冷卻6秒。",
    ["5288c4d"] = "雙手武器都塗 Instant Poison。艱難的戰鬥從潛行用 Cheap Shot，否則直接 Sinister Strike。招架後立刻 Riposte。Shank 冷卻期間用 Sinister Strike 攢點：前五個點給 Slice and Dice，接下來五個給 Eviscerate。",
    ["869d1bf"] = "有兩個怪物貼身時：Blade Flurry（每2分鐘一次，15秒內你攻擊快20%，每次攻擊還會打到附近的第二個目標）。",
    ["9fb5eb8"] = "對危險的怪物用 Adrenaline Rush（每5分鐘一次：15秒內能量回復快一倍）。",
    ["f8cc28b"] = "在大 Eviscerate 之前用 Cold Blood。",
    ["625324b"] = "帶敏捷的皮甲：這就是你要的。命中（Hit）、暴擊、攻擊強度和耐力都有用。Combat 可以使用任何型別的武器，因為 Hack and Slash 對每種武器都給加成：劍和斧、匕首和拳套、錘。",
    ["d01cb25"] = "Assassination 是用毒的：毒藥和終結技越來越強，40級時 Mutilate 到來。",
    ["9eb3d72"] = "雙手武器都塗 Instant Poison。從潛行用 Garrote 或 Cheap Shot 開場。用 Sinister Strike 攢點，Shank 冷卻好就用。Slice and Dice，然後 Eviscerate；把 Cold Blood 留給大 Eviscerate。",
    ["33aceb3"] = "Venom：每次 Shank 之後6秒內，你的毒藥傷害高30%，觸發率高20%。Shank 冷卻好就用。",
    ["88ede56"] = "Mutilate 攢點：用雙手武器攻擊，對中毒目標傷害高20%，並給2個點。需要兩把匕首。Slice and Dice，為 Venom 在冷卻好時 Shank，然後 Eviscerate；大 Eviscerate 時用 Cold Blood。",
    ["20500ff"] = "帶敏捷的皮甲。Assassination 需要匕首來使用 Backstab、Ambush 和 Mutilate。命中（Hit）、暴擊、攻擊強度和耐力都有用。",
    ["5259278"] = "Subtlety 是伏擊者：每場戰鬥都手持匕首從暗處開始。",
    ["64f4a07"] = "主手拿匕首，雙手武器都塗 Instant Poison。繞到怪物背後，Premeditation，然後 Ambush，然後 Ghostly Strike，然後 Garrote。其餘用 Sinister Strike 攢點；為了能量，Shank 冷卻好就用；Eviscerate 收尾。",
    ["37c1365"] = "Hemorrhage 代替 Sinister Strike 攢點。",
    ["c0f22d5"] = "Hemorrhage 和 Shank 攢點，有 Boot Knife 時每個 Shank 算兩個。Death Mark 儲存6秒傷害：當怪物活得夠久時，把一整套點數花在它上面，然後 Eviscerate 收尾。如果戰鬥不順，Preparation 會重置 Premeditation、Ghostly Strike 和你的其他冷卻。",
    ["a993dd2"] = "帶敏捷的皮甲。Subtlety 主手拿匕首（Ambush 和 Backstab 要求如此）。命中（Hit）、暴擊、攻擊強度和耐力都有用。",
    ["abbb551"] = "Earth Shock；大地圖騰任務：Stoneskin Totem",
    ["8e8845b"] = "火焰圖騰任務：Searing Totem",
    ["2be8a5e"] = "Ghost Wolf, Frost Shock, Lesser Healing Wave, Frostbrand Weapon, Healing Stream Totem（水圖騰任務）, Call of the Elements, Totemic Recall",
    ["0a8c77d"] = "Windfury Weapon, Reincarnation（需要 Ankh）, Astral Recall, Grounding Totem",
    ["47fd721"] = "Chain Lightning, Windfury Totem；空氣圖騰任務（風暴武器）",
    ["b821239"] = "Chain Heal，鎖甲",
    ["d6b5209"] = "Rockbiter Weapon 留在武器上，從8級起拉怪前給自己上 Lightning Shield。用 Lightning Bolt 開場，怪物一到就用 Earth Shock，它是瞬發的；對付施法者，留著震擊來打斷它的施法。怪物貼身後，由近戰攻擊收掉它。如果又來一個怪物，放 Earthbind Totem：它會減速怪物，讓你能風箏。戰鬥結束後如果受傷，Healing Wave。",
    ["fa734a3"] = "每個專精都有明確的定位：Enhancement 用大武器、圖騰和震擊近戰；Elemental 用 Lightning Bolt、Chain Lightning 和 Fire Nova 在遠處戰鬥；Restoration 負責治療，待在隊伍或副本里，不適合單人做任務。如果法力耗盡，Enhancement 還能繼續打（擊殺時間更長），Elemental 則更吃虧。",
    ["b74be3c"] = "Flame Shock 立刻造成火焰傷害，然後灼燒12秒。Flametongue Weapon 給每次攻擊增加火焰傷害；Searing Totem 是一個小炮塔，會射擊附近的敵人。",
    ["35c7293"] = "Enhancement 是我們推薦做任務的專精。它有自己的弱點：差的武器會大幅降低傷害，開始時的法力消耗很重，同時面對許多敵人時會吃力。",
    ["028a6b7"] = "Stormstrike 每8秒立刻造成武器的全額傷害，目標會多承受你下一個 Lightning Bolt、Chain Lightning 或 Earth Shock 的20%傷害。",
    ["a94041d"] = "Stormstrike 每次冷卻好就用，之後緊接著 Earth Shock（Stormstrike 的攻擊讓震擊更強）。Rockbiter Weapon 始終在武器上，Lightning Shield 在自己身上。拉怪前 Strength of Earth 和 Mana Spring，法力允許的話 Searing Totem 或 Magma Totem。用1級的 Lightning Bolt（最便宜）開場，其餘由普通攻擊完成。只有當怪物在你火焰圖騰範圍內且你還有法力時才用 Fire Nova。擊殺後 Healing Wave，法力低就喝水。",
    ["18a8896"] = "把 Windfury Weapon 放到武器上代替 Rockbiter：每次攻擊有20%機率額外打出兩次攻擊，這是 Enhancement 的大頭。如果閃避或招架重置了 Stormstrike，立刻再按一次。Windfury Totem，對施法者用 Grounding Totem 取代它。",
    ["f3777c4"] = "Maelstrom Weapon：你的攻擊最多積累5層，每層讓下一個 Lightning Bolt 更快更便宜：5層時施放最高等級的 Lightning Bolt。從46級起，Water Shield 取代 Lightning Shield（只能有一個）。",
    ["022a55d"] = "對 Enhancement，武器最重要：理想的是速度3.3到3.8之間的慢速雙手武器。然後是力量和攻擊強度，智力緊隨其後，因為它為 Mental Dexterity 和法力提供支援。",
    ["4540d89"] = "Earthbound：放置 Earthbind Totem 時，附近的敵人會被困住5秒。",
    ["bcd1d77"] = "拉怪前 Mana Spring Totem 和一個火焰圖騰（對一個怪物用 Searing，對多個怪物用 Magma），給自己上 Lightning Shield。在射程邊緣用 Lightning Bolt 開場，給目標上 Flame Shock，然後繼續 Lightning Bolt。有三個或更多怪物時，Fire Nova 每次冷卻好就用。Earth Shock 打斷施法者並把它引向你。怪物靠近時放 Earthbind Totem。結束時治療並喝水。",
    ["13a3832"] = "面對單個怪物：Searing Totem，從遠處用 Lightning Bolt 開場，Flame Shock，繼續 Lightning Bolt。面對三個或更多：Magma Totem，用 Chain Lightning 開場，對其中一個上 Flame Shock，然後每次冷卻好就 Chain Lightning 和 Fire Nova，中間穿插 Lightning Bolt。",
    ["2c3ba7a"] = "Lightning Mastery（持續15秒，冷卻3分鐘）：15秒內 Lightning Bolt 施放更快，Chain Lightning 無視自己的冷卻。用在精英或大群怪上，否則每次冷卻好就用。",
    ["b56c9ed"] = "Water Shield 取代你身上的 Lightning Shield。",
    ["4688073"] = "對 Elemental 尋找法術強度，智力主要為了法力。40級起可以穿鎖甲。",
    ["b4ca62b"] = "拉怪前 Water Shield、Mana Spring Totem 和隊伍能用的圖騰。有人受傷時，Healing Wave 是主力。Lesser Healing Wave 施法1.5秒，按法力算治療較少：留給時間重要的時刻。當全隊沒法力時用 Mana Tide Totem（12秒，冷卻5分鐘）。沒人有危險時增加傷害：對目標用 Lightning Bolt，對一群怪用 Fire Nova。結束時喝水。",
    ["42937c0"] = "Nature's Swiftness（每3分鐘）：你的下一個自然法術是瞬發，所以可以給快死的朋友一個瞬發的 Healing Wave。如果有玩家在近戰，用 Windfury Totem。",
    ["9b2d19c"] = "Riptide：持續治療，冷卻12秒，對 Riptide 的目標施放的 Chain Heal 強25%。Chain Heal 治療目標和另外兩個盟友，所以能覆蓋分散在隊伍中的傷害。",
    ["a86408d"] = "對 Restoration 尋找治療強度，智力主要為了法力。40級起可以穿鎖甲。",
    ["c86a1be"] = "Voidwalker（職業任務）, Drain Soul, Healthstone",
    ["40cb6b4"] = "Succubus 和 Incubus（職業任務）, Demon Armor, Curse of the Elements, Rain of Fire, Ritual of Summoning",
    ["df7bfa2"] = "Felhunter（職業任務）, Hellfire",
    ["19e5308"] = "Howl of Terror, Felsteed（任務）",
    ["1c5b068"] = "惡魔先上，然後 Bane of Agony 和 Corruption；只有最難纏的怪物才上 Immolate，因為惡魔會拉住它們。順序很重要，因為傷害會吸引注意：Agony 最初的跳傷很小，所以惡魔會拉住怪物，直到新的 Immolate 打得足夠重，讓它轉向你。保持 Demon Skin，對快死的怪物跳過 DOT，並且在它還在造成傷害時不要重新整理 Agony。在你有魔杖之前，由 Shadow Bolt 完成收尾；之後弄一把魔杖：每一發都是為下一次拉怪省下的法力。",
    ["ea42414"] = "Drain Soul 是你獲取 Soul Shard 的主要來源：一個不平凡的怪物死於它的吸取時，總會給一個。碎片少時用它來收掉擊殺。Healthstone、Soul Stone 以及 Voidwalker、Succubus 和 Felhunter 的召喚都需要碎片。",
    ["72f97d5"] = "Drain Life 改變你看螢幕的方式：如果藍條低而你的生命良好，用 Life Tap；如果你的生命真的下降了，對怪物用 Drain Life。這樣幾乎所有的空檔都消失了。",
    ["51205f3"] = "用 Demon Armor 代替 Demon Skin。有 Ritual of Summoning，你和兩個同伴可以把還很遠的隊友召喚過來。一個 Fear 能給你幾秒鐘的免費時間來包紮。",
    ["9d83c05"] = "如果你單人遊玩，Affliction 是首選：命中和瞬發的 Corruption 來得很早。Curse of the Elements 放在 Agony 旁邊。從25級起，Nightfall 可以由 Corruption、Drain Life 或 Drain Soul 的傷害觸發，觸發後的 Shadow Bolt 沒有施法時間。你可以在30級稍前拿吸取天賦，並在每場戰鬥中依靠 Drain Life。",
    ["04f03c2"] = "Siphon Life：30秒內每3秒跳一次傷，所以10秒就死的怪物只吃到三分之一。留給長時間的戰鬥。",
    ["703c37f"] = "Demonic Sacrifice：你犧牲 Felhunter，兩小時內每4秒恢復你總生命的3%；召喚惡魔會取消它，所以從這裡開始你做任務幾乎不帶寵物。",
    ["2dbcea6"] = "Wrack：你引導6秒，造成暗影傷害，在持續期間，你施加在該目標上的其他暗影 DOT 傷害提高10%。",
    ["edb7e47"] = "選擇帶法術強度的武器，因為你幾乎不會用它們來攻擊。開始時魔杖升級勝過幾乎所有其他東西；之後法術強度排第一。耐力是額外的生命，可以用 Life Tap 轉成法力，智力是更大的法力池，精神讓每次 Life Tap 回得更多。",
    ["1c3a6a3"] = "如果你更喜歡看惡魔幹活，選 Demonology：25級起配合 Demonic Brand。從25級起，Searing Pain 在目標上留下一個標記10秒，最多你惡魔的前六次攻擊造成額外傷害：用一個快速的 Searing Pain 打在惡魔正在戰鬥的目標上重新整理它，並用 DOT 和魔杖填補空檔。",
    ["00d4a86"] = "Soul Link：對你的每次直接攻擊的30%轉給惡魔，你們兩個造成的傷害多3%。換惡魔時會失效：每次都要重新施放。",
    ["a3cee7a"] = "Demonic Pact：犧牲在換惡魔後依然有效，除非你召喚的正是你犧牲的那隻。在副本里犧牲 Imp（暗影傷害多15%）；單人任務時犧牲 Felhunter 以獲得它的治療，並與 Voidwalker、Succubus 或 Incubus 並肩作戰。從27級起你也可以用 Affliction 升級並切換專精：你有 Demonic Brand 三個等級所需的點數。",
    ["545f2c9"] = "Destruction 從10級起可玩，但在39和40級會強得多，而且比另外兩個專精更多時間站著施法：也可以以後再選。",
    ["0b5d29c"] = "Shadowburn：一次瞬發攻擊，消耗一個碎片，如果一個不平凡的目標在8秒內死亡就返還碎片。",
    ["124afde"] = "開場改變了：從最大距離用 Shadow Bolt，在箭矢還在飛行時上 Immolate。這樣怪物會衝向你而不是惡魔，所以選擇你能快速結束的戰鬥。Shadowburn 收掉怪物；最好把 Conflagrate 留到你的 Immolate 快結束時。",
    ["07ea333"] = "有 Shadow and Flame 時，Conflagrate 讓你的暗影傷害提高20%，Shadowburn 讓你的火焰傷害提高20%；Conflagrate 不再消耗 Immolate，Shadowburn 總是返還碎片。從39級起沒有理由再保留它們。",
    ["609f38c"] = "Incinerate 對已經被你的 Immolate 灼燒的一切多造成25%傷害。",
    ["a1d5005"] = "Defensive Stance, Taunt, Sunder Armor（職業任務）, Bloodrage",
    ["b87bfb2"] = "Revenge, Demoralizing Shout, Tactical Mastery（嚮導師學習）",
    ["a61955b"] = "Victory Rush, Cleave, Slam, Retaliation；你可以使用雙武器",
    ["323f468"] = "Berserker Stance, Berserker Rage, Intercept（職業任務）",
    ["b289adb"] = "板甲和坐騎",
    ["2debde0"] = "拉怪前 Battle Shout，Charge，對活得久的怪物用 Rend，然後讓普通攻擊積累怒氣。只在有不需要的怒氣時才用 Heroic Strike：它取代一次普通攻擊，而那次攻擊不給怒氣。有多個怪物時用 Thunder Clap；不要在快死的怪物身上花怒氣。",
    ["f98c5d6"] = "兩次拉怪之間用 Bloodrage：它消耗一點生命，立刻給10點怒氣，10秒後再給10點。永遠不要在沒有怒氣的情況下開始戰鬥。",
    ["970305a"] = "Victory Rush 每次亮起就用：在一次給經驗的擊殺之後你有20秒，它造成傷害並治療你10%，冷卻30秒，不消耗怒氣。",
    ["a60b4a3"] = "從14級起 Revenge 是你的主要攻擊：每次亮起就用（在格擋、閃避或招架之後）。換成盾牌和單手武器。對群怪用 Thunder Clap 和 Demoralizing Shout。",
    ["41fd2f0"] = "Charge，然後留在 Defensive Stance。對近戰攻擊你的怪物保持 Shield Block，對施法者則跳過 Shield Block。Revenge 每次亮起就用；對活得久的怪物用 Rend 和幾個 Sunder Armor；對群怪用 Thunder Clap 和 Demoralizing Shout。",
    ["b604238"] = "有 Vanguard 時，你可以在 Defensive Stance 中使用 Charge：如果你脫離戰鬥，可以不換姿態就開始一次拉怪。",
    ["c9e7c22"] = "Shield Wall：12秒內傷害減少60%，用於不順利的拉怪。",
    ["3f0c2f4"] = "Shield Slam 是最強的一擊（傷害隨你的格擋值增長）：先用它，之後立刻 Revenge。如果怒氣少，先 Revenge，它消耗更少。",
    ["846367b"] = "Protection 主要想要力量（每點給2點攻擊強度和格擋值）。武器選DPS最高的：Revenge 和 Shield Slam 不依賴武器。敏捷不那麼重要：它給暴擊、閃避和護甲，但不給攻擊強度。",
    ["fabdcb6"] = "先 Rend，然後每次亮起就 Overpower（在目標閃避之後）。",
    ["f29cf52"] = "Rend，然後亮起時 Overpower。從20級起，一次攻擊之後立刻 Slam。",
    ["60998aa"] = "Sweeping Strikes：你接下來的五次攻擊也會打到附近的第二個敵人，這是一次大飛躍。在有多餘怒氣時先對一個怪物開打，然後拉來第二個怪物，對兩個都用 Sweeping Strikes 和 Cleave。",
    ["efc030d"] = "有 Bloodthrill 時，如果目標身上有 Rend，你的主手攻擊有20%的機率觸發 Overpower：Rend 會一直留在輸出循環中到60級。",
    ["98a8fec"] = "Mortal Strike 是你新的主要攻擊。",
    ["7caf705"] = "武器比一切都重要：尋找最高的DPS，Arms 要慢速雙手武器（每次攻擊以及 Mortal Strike 和 Slam 造成更多傷害）。其餘屬性先看命中（Hit，因為未命中既沒有傷害也沒有怒氣），然後是力量和暴擊。敏捷給暴擊和閃避，但不給攻擊強度。",
    ["ce62f29"] = "對活得久的怪物用 Rend，目標閃避時用 Overpower。如果第二個怪物在目標旁邊，把多餘的怒氣花在 Cleave 上。選一把快速的副手武器：攻擊更多，怒氣更多。",
    ["1879df1"] = "Death Wish：30秒內你造成的物理傷害多20%且不會被恐懼，但承受的傷害多5%。Reckless Swings（31）：消耗一點生命，你接下來的四次攻擊每次多給5點怒氣。",
    ["0d27ce4"] = "有 Whirlwind（36級）時它是你的主要按鍵，即使面對單個怪物：冷卻降到8秒，並以多30%的傷害打擊最近的目標。",
    ["308a3c5"] = "每當 Whirlwind 在冷卻中就用 Bloodthirst。從50級起你有 Recklessness。",
    ["2d76abd"] = "武器比一切都重要：尋找最高的DPS。副手用快速的（攻擊更多，怒氣更多）。其餘屬性先看命中（Hit），然後是力量和暴擊。敏捷給暴擊和閃避，但不給攻擊強度。",
}
